    "presetQuestions": {
      "title": "Essayez",
      "focus": "Centrez-vous sur",
      "interests": {
        "personalKnowledge": "Connaissance personnelle",
        "learningGrowth": "Apprentissage et progression",
        "contentCreation": "Création de contenu",
        "marketInvesting": "Marchés et investissement",
        "productDesign": "Design produit",
        "userResearch": "Recherche utilisateur",
        "psychologicalExploration": "Exploration psychologique",
        "philosophicalDialogue": "Dialogue philosophique"
      },
      "refresh": "Plus",
      "examples": {
        "memoryBank": {
          "title": "Banque de mémoire numérique",
          "description": "Transforme mes échanges, e-mails, photos et documents en une chronologie de vie consultable à tout moment.",
          "prompt": "Organise mon historique de chat, mes e-mails, les métadonnées de mes photos et mes documents en un système de mémoire personnel. Extrais le temps, le lieu, les personnes, les événements et les mots-clés, utilise l’OCR si nécessaire, construis une chronologie et un index thématique consultables, puis réponds aux questions ultérieures avec ce qui s’est passé, les preuves et la chronologie."
        },
        "readingCompanion": {
          "title": "Compagnon de lecture quotidien",
          "description": "Choisis chaque jour ce qui mérite vraiment d’être lu, puis aide-moi à le comprendre et à y réfléchir.",
          "prompt": "Suis les sources autour des thèmes qui m’intéressent et fais remonter chaque jour les trois lectures les plus utiles. Pour chacune, fournis un résumé, les idées clés, les points discutables et deux questions de discussion, archive le tout par thème et suis ma progression de lecture ainsi que l’évolution de mes centres d’intérêt."
        },
        "growthMap": {
          "title": "Carte de progression personnelle",
          "description": "Transforme cours, projets, notes et habitudes de révision en une carte de compétences vivante qui me dit quoi apprendre ensuite.",
          "prompt": "Combine mes cours, mes commits de projet, mes notes et mes fiches de connaissance en une carte de progression personnelle. Identifie les compétences acquises, mes points faibles et les zones de stagnation, planifie la révision espacée et recommande les ressources et exercices les plus utiles pour la suite."
        },
        "contentPlanner": {
          "title": "Planificateur de contenu multi-plateforme",
          "description": "Observe les tendances sur X, Reddit et YouTube, puis transforme-les en un pipeline de contenu prêt à publier.",
          "prompt": "Suis les sujets IA logiciels qui montent rapidement sur X, Reddit et YouTube. Extrais les récits, conflits et angles qui prennent de l’ampleur, puis transforme-les en une semaine d’idées de contenu avec angles de titre, plans de script, suggestions d’horaire de publication et indicateurs de revue."
        },
        "chipMarketBriefing": {
          "title": "Brief d’ouverture des semi-conducteurs",
          "description": "Lis une page avant l’ouverture et comprends ce qui a changé sur NVDA, AMD et la chaîne des puces.",
          "prompt": "Génère un brief pré-ouverture centré sur NVDA, AMD et la chaîne des semi-conducteurs. Résume les mouvements de prix de la nuit, les actualités importantes, les avis d’analystes, le sentiment de marché et les catalyseurs possibles, puis présente ce qui s’est passé, pourquoi c’est important et ce qu’il faut surveiller aujourd’hui."
        },
        "morningBriefing": {
          "title": "Brief matinal personnel",
          "description": "Fusionne mon agenda, mes e-mails, mes tâches et l’actualité en un brief matinal avec de vraies priorités.",
          "prompt": "Crée chaque matin un brief qui rassemble mon calendrier, l’activité e-mail, mes tâches et les actualités pertinentes. Classe les trois priorités du jour, signale les risques probables et propose le meilleur ordre d’action pour que je sois opérationnel en trois minutes."
        },
        "macroTracker": {
          "title": "Décodeur de données économiques",
          "description": "Suis les publications macro et transforme les mises à jour brutes en explication concrète de leur portée.",
          "prompt": "Surveille les données macro publiques de la Réserve fédérale, des instituts statistiques et de sources similaires avec comparaisons historiques et alertes d’anomalie. À chaque nouvelle publication, explique ce qui a changé, ce que cela peut signifier pour les différentes classes d’actifs, où le marché peut se tromper et quels scénarios méritent de l’attention."
        },
        "designAdaptation": {
          "title": "Adaptation multi-appareil en un clic",
          "description": "À partir d’un seul design, déduis rapidement des adaptations desktop, tablette et mobile avec une checklist de handoff.",
          "prompt": "À partir de mon fichier de design ou de ma spec UI, produis un plan d’adaptation multi-appareil. Identifie les structures de mise en page, les composants réutilisables et les points de rupture clés, puis fournis des recommandations par appareil, les changements de spec et une checklist de handoff avec les principaux risques techniques."
        },
        "inspirationFeed": {
          "title": "Inspiration design infinie",
          "description": "Apprends mes goûts et alimente-moi en références qui ne sont pas seulement proches, mais réellement réutilisables.",
          "prompt": "Collecte et organise des références fortes autour des styles visuels que je préfère. Classe-les par mise en page, couleur, texture, ambiance et langage d’interaction, recommande des références voisines et transforme chaque sélection en moodboard et note de direction visuelle directement exploitables."
        },
        "sentimentRadar": {
          "title": "Radar de sentiment utilisateur",
          "description": "Écoute les variations émotionnelles dans les commentaires et les communautés, puis détecte ce qui préoccupe vraiment les utilisateurs sans encore être résolu.",
          "prompt": "Surveille les posts de communauté, les discussions sociales et les commentaires vidéo pour identifier le sentiment, les plaintes répétées, les attentes fréquentes et les points de vue polarisés. Va au-delà des étiquettes de sentiment et résume les vrais problèmes, les segments probables, les besoins non satisfaits et les opportunités produit à valider."
        },
        "dreamDialogue": {
          "title": "Dialogue des symboles du rêve",
          "description": "N’explique pas mon rêve à ma place. Pose-moi les questions qui m’aident à le relier à ma vie réelle.",
          "prompt": "Quand je décris un rêve, ne saute pas vers une interprétation standard. Pose des questions de suivi qui relient les scènes, les personnes et les émotions du rêve à mes expériences réelles, construis un lexique personnel des symboles de rêve et suis l’évolution des thèmes récurrents."
        },
        "aristotleDialogue": {
          "title": "Dialogue de l’âme : Aristote",
          "description": "Transforme les écrits et la méthode d’Aristote en un conteneur durable avec lequel je peux continuer à penser.",
          "prompt": "Construis un conteneur de connaissance prêt pour le dialogue autour des œuvres d’Aristote, de sources historiques fiables et de ses idées centrales. Dégage ses concepts, ses jugements de valeur, son style argumentatif et ses schémas de questionnement, puis réponds dans son style en distinguant clairement doctrine originale, inférence raisonnable et prolongement moderne."
        }
      }
    },
